powerpagecomponent.content:
{
  "source": "{% include 'Compliance Settings' %}
<div class="wrapper-body">
    <div class="container">
        <div class="page-heading">
            {% block breadcrumbs %}
            {% include 'Breadcrumbs' %}
            {% endblock %}
            {% block title %}
            {% endblock %}
        </div>
    </div>
    <div id="mainContent">
        {% block main %}
        {% include 'Page Copy' %}

        {% endblock %}
    </div>
    <div class="push"></div>
</div>"
}
